using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Web;
using System.Web.Script.Serialization;
using System.Diagnostics;
using System.Threading;
using System.Net.Sockets;
namespace SplifyWin {
 public sealed class QwdttProfile {
  public string Name,Host,Password;public int Port,Workers;public string[] Hashes;
  public static QwdttProfile Parse(string raw){
   Uri uri;if(!Uri.TryCreate(raw.Replace("qwdtt:config","qwdtt://config"),UriKind.Absolute,out uri)||uri.Scheme!="qwdtt"||uri.Host!="config"||uri.UserInfo.Length>0)throw new FormatException("Нужна ссылка qwdtt://config из клиента SpaceNeuroX.");
   var q=HttpUtility.ParseQueryString(uri.Query);if(q.AllKeys.Any(k=>k==null||q.GetValues(k).Length!=1))throw new FormatException("Повторяющиеся параметры QWDTT.");string peer=q["peer"]??"";if(!peer.Contains(":"))peer+=":56000";Uri endpoint;if(!Uri.TryCreate("udp://"+peer,UriKind.Absolute,out endpoint)||endpoint.UserInfo.Length>0||endpoint.Port<1||endpoint.Port>65535||endpoint.AbsolutePath!="/"||Uri.CheckHostName(endpoint.Host.Trim('[',']'))==UriHostNameType.Unknown)throw new FormatException("Некорректный адрес сервера QWDTT.");
   string password=q["pass"]??q["password"];if(String.IsNullOrEmpty(password)||password.Length>1024||password.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new FormatException("Укажите пароль подключения QWDTT.");var hashes=(q["hashes"]??"").Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(h=>h.Trim()).ToArray();if(hashes.Length>32||hashes.Any(h=>!Regex.IsMatch(h,@"^[A-Za-z0-9_=-]{6,2048}$")))throw new FormatException("Некорректные хеши звонков QWDTT.");int workers=9;if(q["workers"]!=null&&(!Int32.TryParse(q["workers"],out workers)||workers<1||workers>108))throw new FormatException("QWDTT: от 1 до 108 потоков.");return new QwdttProfile{Name=q["name"]??"QWDTT · "+endpoint.Host,Host=endpoint.Host.Trim('[',']'),Port=endpoint.Port,Password=password,Hashes=hashes,Workers=workers};
  }
  public static string Link(string name,string peer,string password,string hashes){return "qwdtt://config?name="+Uri.EscapeDataString(name)+"&peer="+Uri.EscapeDataString(peer)+"&pass="+Uri.EscapeDataString(password)+"&hashes="+Uri.EscapeDataString(hashes);}
 }
 public static class QwdttEngine {
  // This upstream client puts the literal -listen port into the WireGuard
  // Endpoint returned by GETCONF. Passing :0 binds a real ephemeral socket,
  // but advertises endpoint :0 and leaves the tunnel unable to pass traffic.
  internal static string RelayListenAddress(){using(var socket=new UdpClient(new System.Net.IPEndPoint(System.Net.IPAddress.Loopback,0)))return "127.0.0.1:"+((System.Net.IPEndPoint)socket.Client.LocalEndPoint).Port;}
  public static void Start(NetworkCore core,ServerNode node,int port,Action<Process> register,Action<string> log,CancellationToken token){
   var profile=QwdttProfile.Parse(node.Link);if(profile.Hashes.Length==0)throw new InvalidOperationException("Для QWDTT добавьте хеш или ссылку звонка VK в профиль подключения.");if(!File.Exists(core.QwdttExecutable))throw new FileNotFoundException("Скачайте QWDTT в разделе «Обновления → Дополнительные движки».");string config=Path.Combine(core.DataRoot,"qwdtt-start-"+Guid.NewGuid().ToString("N")+".json");SecretStorage.WriteRuntime(config,new JavaScriptSerializer().Serialize(new{peer=(profile.Host.Contains(":")?"["+profile.Host+"]":profile.Host)+":"+profile.Port,hashes=String.Join(",",profile.Hashes),password=profile.Password,workers=profile.Workers,device_id=TurnEngines.DeviceId()}));
   Process child=null;try{var info=new ProcessStartInfo(core.QwdttExecutable,"-startup-config "+ZapretRuntime.Quote(config)+" -mode socks -listen "+RelayListenAddress()+" -socks 127.0.0.1:"+port+" -captcha-mode wv"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=core.DataRoot,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};int ready=0;int captchaWaiting=0;string error="";var gate=new object();child=new Process{StartInfo=info};Action<string> receive=line=>{if(line==null)return;if(line.StartsWith("PROXY_READY|")){Interlocked.Exchange(ref ready,1);log("QWDTT: локальный SOCKS5 готов");}else if(line.StartsWith("CAPTCHA_SOLVE|")){string[] parts=line.Split(new[]{'|'},4);if(parts.Length!=4||!VkCalls.AllowedPage(parts[2])||core.ManualTurnCaptcha==null){lock(gate)error="Не удалось открыть ручную капчу VK.";return;}Interlocked.Exchange(ref captchaWaiting,1);System.Threading.Tasks.Task.Run(async()=>{try{string proof=await core.ManualTurnCaptcha(parts[2],token);if(child!=null&&!child.HasExited){child.StandardInput.WriteLine("CAPTCHA_RESULT|"+(VkCalls.ValidProof(proof)?proof:"error:cancelled"));child.StandardInput.Flush();}}catch{try{if(child!=null&&!child.HasExited){child.StandardInput.WriteLine("CAPTCHA_RESULT|error:cancelled");child.StandardInput.Flush();}}catch{}}finally{Interlocked.Exchange(ref captchaWaiting,0);}});}else if(line.IndexOf("CAPTCHA_REQUIRED",StringComparison.OrdinalIgnoreCase)>=0||line.Contains("CAPTCHA_WAIT")){lock(gate)error="VK требует ручную капчу. Автоматическое подключение не подтверждено.";}else if(line.Contains("DENIED")||line.Contains("STARTUP_CONFIG_")){lock(gate)error="Сервер QWDTT отклонил параметры или авторизацию.";}};child.OutputDataReceived+=(s,e)=>receive(e.Data);child.ErrorDataReceived+=(s,e)=>receive(e.Data);if(!child.Start())throw new IOException("QWDTT не запустился.");OwnedJob.Attach(child);register(child);child.BeginOutputReadLine();child.BeginErrorReadLine();var clock=Stopwatch.StartNew();while(Volatile.Read(ref ready)==0){token.ThrowIfCancellationRequested();if(child.HasExited)throw new IOException("QWDTT завершился до готовности. "+error);if(clock.ElapsedMilliseconds>(Volatile.Read(ref captchaWaiting)==1?240000:180000))throw new TimeoutException("QWDTT не подтвердил соединение за 180 секунд. "+error);Thread.Sleep(50);}using(var socket=new TcpClient("127.0.0.1",port)){socket.GetStream().Write(new byte[]{5,1,0},0,3);socket.ReceiveTimeout=2000;byte[] answer=new byte[2];int read=0;while(read<answer.Length){int count=socket.GetStream().Read(answer,read,answer.Length-read);if(count==0)break;read+=count;}if(read!=2||answer[0]!=5||answer[1]!=0)throw new IOException("QWDTT: SOCKS5 не подтвердил готовность.");}
   }finally{if(File.Exists(config))File.Delete(config);}
  }
 }
}
